import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const MAX_BODY = 1024 * 1024;
const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

interface FieldError {
  field: string;
  message: string;
}

function send(res: ServerResponse, status: number, body: unknown, extra: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store', ...extra });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[], extra?: Record<string, string>): void {
  send(res, status, { error: fields ? { code, message, fields } : { code, message } }, extra);
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (c: Buffer) => {
      size += c.length;
      if (size > MAX_BODY) tooLarge = true;
      else chunks.push(c);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

const getById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const getByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const listAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const insertJob = db.prepare(`INSERT INTO jobs (id, status, input, steps, fail_attempts, created_at, updated_at, run_after, idempotency_key, payload)
  VALUES (?, 'queued', ?, ?, ?, ?, ?, 0, ?, ?)`);
const getBeat = db.prepare("SELECT beat_at FROM heartbeat WHERE name = 'worker'");

function validate(body: unknown, errors: FieldError[]): { input: string; steps: number; failAttempts: number } | null {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    errors.push({ field: 'body', message: 'Body must be a JSON object.' });
    return null;
  }
  const obj = body as Record<string, unknown>;
  for (const k of Object.keys(obj)) {
    if (!['input', 'steps', 'failAttempts'].includes(k)) errors.push({ field: k, message: 'Unknown field.' });
  }
  const input = obj.input;
  if (input === undefined) errors.push({ field: 'input', message: 'input is required.' });
  else if (typeof input !== 'string') errors.push({ field: 'input', message: 'input must be a string.' });
