import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, MAX_ATTEMPTS, type JobRow } from './db.ts';

const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const LEASE_MS = 3000;
const POLL_MS = 100;

const db = openDatabase();
let stopping = false;
let wake: (() => void) | null = null;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
    wake?.();
  });
}

const beatStmt = db.prepare("INSERT INTO heartbeat (name, beat_at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET beat_at = excluded.beat_at");
function beat(): void {
  try {
    beatStmt.run(Date.now());
  } catch (err) {
    console.error('heartbeat failed', err);
  }
}
beat();
const beatTimer = setInterval(beat, 500);

const selectNext = db.prepare(`SELECT * FROM jobs
  WHERE (status = 'queued' AND run_after <= ?) OR (status = 'running' AND (lease_until IS NULL OR lease_until < ?))
  ORDER BY seq ASC LIMIT 1`);
const claimStmt = db.prepare(`UPDATE jobs SET status = 'running', attempts = MIN(attempts + 1, ${MAX_ATTEMPTS}), progress_completed = 0,
  result_output = NULL, error = NULL, lease_until = ?, updated_at = ? WHERE id = ?`);
const getById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const progressStmt = db.prepare(`UPDATE jobs SET progress_completed = ?, lease_until = ?, updated_at = ?
  WHERE id = ? AND status = 'running' AND attempts = ?`);
const completeStmt = db.prepare(`UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL,
  lease_until = NULL, updated_at = ? WHERE id = ? AND status = 'running' AND attempts = ?`);
const retryStmt = db.prepare(`UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, lease_until = NULL, updated_at = ?
  WHERE id = ? AND status = 'running' AND attempts = ?`);
const failStmt = db.prepare(`UPDATE jobs SET status = 'failed', progress_completed = 0, result_output = NULL, error = ?, lease_until = NULL,
  updated_at = ? WHERE id = ? AND status = 'running' AND attempts = ?`);
const requeueStmt = db.prepare(`UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, lease_until = NULL, updated_at = ?
  WHERE id = ? AND status = 'running' AND attempts = ?`);

function claim(): JobRow | null {
  db.exec('BEGIN IMMEDIATE');
  try {
    const now = Date.now();
    const row = selectNext.get(now, now) as unknown as JobRow | undefined;
    if (!row) {
      db.exec('COMMIT');
      return null;
    }
    claimStmt.run(now + LEASE_MS, new Date(now).toISOString(), row.id);
    const claimed = getById.get(row.id) as unknown as JobRow;
    db.exec('COMMIT');
    return claimed;
  } catch (err) {
    try { db.exec('ROLLBACK'); } catch { /* ignore */ }
    throw err;
  }
}

async function processJob(job: JobRow): Promise<void> {
  const attempt = job.attempts;
  const iso = () => new Date().toISOString();
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      // Hand the job back so the next worker picks it up immediately.
      requeueStmt.run(iso(), job.id, attempt);
      return;
    }
    if (step === 1 && attempt <= job.fail_attempts) {
      if (attempt >= MAX_ATTEMPTS) failStmt.run('transient failure', iso(), job.id, attempt);
      else retryStmt.run(Date.now() + RETRY_DELAY_MS, iso(), job.id, attempt);
      return;
    }
    if (step === job.steps) {
      completeStmt.run(job.input.toUpperCase(), iso(), job.id, attempt);
      return;
    }
    const r = progressStmt.run(step, Date.now() + LEASE_MS, iso(), job.id, attempt);
    if (Number(r.changes) === 0) return; // lost ownership
  }
}

console.log('worker started');
while (!stopping) {
  let job: JobRow | null = null;
  try {
    job = claim();
  } catch (err) {
    console.error('claim failed', err);
  }
  if (job) {
    try {
      await processJob(job);
    } catch (err) {
      console.error('processing failed', err);
    }
    continue;
  }
  await new Promise<void>((resolve) => {
    const t = setTimeout(resolve, POLL_MS);
    wake = () => {
      clearTimeout(t);
      resolve();
    };
  });
  wake = null;
}
clearInterval(beatTimer);
try { db.close(); } catch { /* ignore */ }
console.log('worker stopped');
process.exit(0);

